br.script:
var c = document.getElementById('c'), ctx = c.getContext('2d');
var g = ctx.createLinearGradient(0, 0, 512, 512);
g.addColorStop(0, '#075c43'); g.addColorStop(1, '#0a8a63');
ctx.fillStyle = g;
ctx.beginPath();
ctx.moveTo(96, 0); ctx.arcTo(512, 0, 512, 512, 96); ctx.arcTo(512, 512, 0, 512, 96);
ctx.arcTo(0, 512, 0, 0, 96); ctx.arcTo(0, 0, 512, 0, 96); ctx.closePath(); ctx.fill();
ctx.strokeStyle = '#fff'; ctx.lineWidth = 26; ctx.lineCap = 'round'; ctx.lineJoin = 'round';
ctx.beginPath();
ctx.moveTo(96, 128); ctx.lineTo(150, 128); ctx.lineTo(206, 340); ctx.lineTo(392, 340); ctx.lineTo(436, 190); ctx.lineTo(180, 190);
ctx.stroke();
ctx.fillStyle = '#fff';
ctx.beginPath(); ctx.arc(232, 404, 26, 0, Math.PI * 2); ctx.fill();
ctx.beginPath(); ctx.arc(372, 404, 26, 0, Math.PI * 2); ctx.fill();
document.getElementById('btn').addEventListener('click', function () {
  [192, 512].forEach(function (tam) {
    var fora = document.createElement('canvas');
    fora.width = tam; fora.height = tam;
    fora.getContext('2d').drawImage(c, 0, 0, tam, tam);
    var a = document.createElement('a');
    a.download = 'icon-' + tam + '.png';
    a.href = fora.toDataURL('image/png');
    a.click();
  });
});
